from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];s=json.loads((R/'reports/v132/packed_validation_summary.json').read_text(encoding='utf-8'));assert s['passed']
B=R.parent/'pynq_z2_tile_v1_25';old=json.loads((B/'DELIVERY_MANIFEST.json').read_text(encoding='utf-8'))['validation']['transport']['summary']['transport_noise']
n=s['transport']['summary']['transport_noise'];a=s['identity'];c=s['station']
rows=''.join(f"<tr><td>{name}</td><td>{v['raw']['request_ms']:.2f}</td><td>{v['legacy']['request_ms']:.2f}</td><td>{v['compact']['request_ms']:.2f}</td><td>{v['compact']['wire_saving_percent']:.4f}%</td></tr>" for name,v in s['transport']['summary'].items())
html=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TileLab V1.26 实板验证</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#edf4f4;color:#173e47;font:16px/1.8 system-ui}}main{{max-width:1050px;margin:30px auto;padding:30px;background:white;border-radius:18px}}a{{color:#087d80}}.grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}}.metric{{background:#edf6f5;border-radius:12px;padding:18px}}.metric b{{display:block;font-size:28px}}.note{{background:#fff0df;padding:18px;border-left:4px solid #ba772c}}h1{{font-size:32px}}table{{width:100%;border-collapse:collapse}}td,th{{padding:10px;border-bottom:1px solid #d5e4e6;text-align:left}}small{{color:#55767c}}@media(max-width:700px){{.grid{{grid-template-columns:1fr}}main{{margin:0;padding:20px}}}}</style><main><a href="/">← 返回检测工作台</a><p>V1.26 · 实板逐项验收完成</p><h1>编码一部分，发送一部分</h1><p>无损 PACK25 编码与 TCP 发送重叠。保留 V1.24 检测硬件、74.25 MHz 和 720p60；识别继续在 FPGA 中完成。</p><div class="grid"><div class="metric">难压缩画面负载减少<b>21.875%</b><small>3,686,400 → 2,880,000 字节</small></div><div class="metric">省流请求中位数<b>{n['compact']['request_ms']:.2f} ms</b><small>V1.25 为 {old['compact']['request_ms']:.2f} ms；两版不同时间测量</small></div><div class="metric">同事件逐字节验证<b>50 组 / 150 次</b><small>原图、掩码、描述及 CRC 一致</small></div></div>
<h2>保持可回退，按实测选择模式</h2><p>颜色前缀完成即可发送；掩码平面等整帧完成才发送。每轮仍最多处理 2048 像素，不增加整帧缓存。默认保持原有策略，可在工作台选择省流。</p><table><thead><tr><th>输入</th><th>RAW ms</th><th>旧自适应 ms</th><th>重叠省流 ms</th><th>负载减少</th></tr></thead><tbody>{rows}</tbody></table><p>这是应用请求耗时，包含主机还原与校验；不等于纯网线速度，也不意味着电脑预览 60 fps。</p>
<h2>半包与错误没有被掩盖</h2><p>复核 AMD 网口驱动后，补上 TCP 中止但网卡仍持有缓存的边界。先复现反例，再采用有界数据副本；{s['stream_native']['gem_retained_reference_checks']} 次模拟 GEM 保留引用检查通过。RAW 用已有小缓存对齐搬运，避免直接逐字节读取 DDR 的开销。</p><p>真实 DDR 在像素 100 与 800000 注入非法位，分别验证发头前、发出部分图像后中止；重试 RAW 完整保留错误，主机 CRC 拒绝，恢复后下一事件重新正常打包。198 项主机测试、13 类网络故障、3 类保存后重启通过。连续运动 {c['seconds']:.2f} 秒保存 {c['saved']} 个缺陷产品各一张最佳图，最大居中偏差 {a['max_center_error_px']} 像素；掩码、框、面积对照一致，无新增采集错误。</p>
<div class="note"><strong>仍然是有适用范围的工程样机</strong><p>没有新增算法盲测；跨材质误报、真实相机曝光和运动模糊仍待解决。五个原有 CDC 不安全端点、有限 DDR 队列和未传出证据掉电丢失等限制保留。网络与进程故障注入不是物理拔电测试。</p></div><p><a href="/api/benchmark">完整实板验证 JSON</a> · docs/Tile_V1.26_分块传输与同步实板报告.md</p></main></html>'''
(R/'host/benchmark.html').write_text(html,encoding='utf-8')
p=R/'README.md';t=p.read_text(encoding='utf-8').replace('实现与验收进行中。','实现、构建和实板验收已完成。').replace('默认保持原兼容策略，实际速度和板端可靠性尚待本版验证。不能把旧版报告视为本版验收。','默认维持旧自适应策略，省流可选；实际速度和可靠性结果见本版报告与 DELIVERY_MANIFEST.json。')
t+='\n本版同时修复 TCP 中止后网卡 DMA 仍可持有应用缓存的边界：发送使用协议栈拥有的副本，RAW 先通过已有小缓存对齐搬运。三阶段试验与缓存反例分别保留；安全保护有复制开销，RAW 比前版慢，最终省流与普通模式对噪声耗时约相当。\n'
t+='\n完整报告：[V1.26 分块传输与同步实板报告](docs/Tile_V1.26_分块传输与同步实板报告.md)；学习说明：[流式传输原理](docs/V1.26_流式传输学习说明.md)。\n'
p.write_text(t,encoding='utf-8');print('Published measured V1.26 verification page')
